insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('89f5bb68-ba04-4fd8-a55c-6a453ce94096', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante analiza las fuerzas que actúan sobre un semáforo, de tal manera que la tensión de las cuerdas lo sostenga en reposo. Él construye la siguiente ecuación y gráfica:</p><p style="font-family:var(--font-mono);text-align:center">Tensión = mg ÷ (2 · sen α)</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q99-semaforo.webp" loading="lazy" alt="Semáforo colgado de dos cuerdas que van a dos postes, uno a cada lado. Cada cuerda forma un ángulo α con la horizontal, marcada con una línea punteada, y sobre cada una se dibuja la tensión apuntando hacia el poste."></figure><p>Donde m es la masa del semáforo, g la aceleración gravitacional y α es el ángulo que forman las cuerdas con respecto a un eje horizontal, y tiene una variación máxima de 90°.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a68e8261-2a8a-49a3-b619-775ad3c63932', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Isabel necesita instalar tres bombillas idénticas en un salón de eventos, en el que se requiere una bombilla en la parte de atrás y dos en la parte de adelante. Ella realiza el siguiente diagrama del circuito:</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q100-circuito.webp" loading="lazy" alt="Circuito con una fuente de energía y un interruptor. La bombilla 1 está sola sobre el cable principal; después el cable se abre en un rectángulo donde la bombilla 2 y la bombilla 3 están en ramas separadas, una en paralelo con la otra."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('f20518d7-c0b3-4d08-bc0a-654e2136fcbc', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Cuando las ondas viajan al interior de una cubeta con agua, entre una región más profunda a una menos profunda, sobre un obstáculo, experimentan una disminución de su velocidad de propagación y su longitud de onda, pero mantiene la misma amplitud.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c1f1693e-f444-4ca8-bdd1-9474d48d198c', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un grupo de científicos diseñó un panel que funciona durante la noche, a diferencia del panel solar. El panel funciona aprovechando el flujo de calor entre el suelo caliente y el ambiente frío, para transformarlo en corriente eléctrica, como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q102-panel.webp" loading="lazy" alt="Corte del panel sobre una mesa. Arriba, un vidrio protector y una lámina de aluminio expuestos al ambiente frío; abajo, la tierra cálida. Entre los dos, un generador termoeléctrico recibe el flujo de calor que sube del suelo y entrega corriente, que enciende un bombillo."></figure><p>El panel se coloca sobre una mesa que tiene un vidrio en la parte superior, para proteger el sistema del viento. El generador termoeléctrico aprovecha el calor proveniente del suelo, para transformar parte de este en corriente eléctrica, que enciende un bombillo. Otra parte del calor se libera hacia el ambiente a través de la lámina de aluminio pintada de negro. Un panel de 1 m² logra encender un bombillo pequeño.</p><p>El calor específico es una medida de la capacidad de un material para cambiar de temperatura cuando se le suministra cierta cantidad de calor. Cuanto mayor es el calor específico, mayor es la energía que se requiere para aumentar la temperatura del material.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4d2da40e-1d04-455a-81af-7af5dc5fdd26', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Sebastián realiza un experimento para organizar diferentes materiales según sus características, escogiendo madera, acero y agua, en donde dichos materiales tienen la misma masa. Los resultados de su experimento se muestran en la siguiente tabla.</p><table class="ctx-table"><tr><th>Material</th><th>Densidad (kg/m<sup>3</sup>)</th><th>Calor específico (kCal/kg °C)</th><th>Tiempo en llegar a 35 °C (s)</th></tr><tr><td>Madera</td><td>400</td><td>0,12</td><td>39</td></tr><tr><td>Acero</td><td>7.850</td><td>0,57</td><td>9</td></tr><tr><td>Agua</td><td>1.000</td><td>1,07</td><td>70</td></tr></table>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d879c9ab-dac2-4645-b655-2546a57d6b3f', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una estudiante mide la presión y el volumen de aire cuando comprime el émbolo que hay sobre un tubo cerrado en uno de sus extremos, como se observa en la figura. Los datos obtenidos se muestran en la tabla.</p><table class="ctx-table"><tr><th>Presión ejercida sobre el émbolo (atm)</th><th>Volumen de aire dentro del tubo (cm<sup>3</sup>)</th></tr><tr><td>0,10</td><td>10</td></tr><tr><td>0,20</td><td>5</td></tr><tr><td>0,30</td><td>3,3</td></tr><tr><td>0,40</td><td>2,5</td></tr></table><figure class="ctx-fig"><img src="img/figuras/fis/f2-q104-tubo.webp" loading="lazy" alt="Dos tubos cerrados por abajo con un émbolo encima. En el primero el émbolo está arriba y la columna de aire es larga; en el segundo, una flecha indica que el émbolo bajó y la columna de aire quedó corta."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d7c16487-1f2f-4f87-9721-2869af2819d9', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Juan observa el movimiento de una atracción mecánica en la feria del pueblo. Él nota que a medida que la atracción gira más rápido, el ángulo entre el brazo horizontal y el brazo que sostiene la silla donde está sentada una compañera aumenta, como se muestra en las siguientes figuras.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q105-atraccion.webp" loading="lazy" alt="Dos esquemas de la misma atracción. En el primero la velocidad de giro es 5,6 metros por segundo, el brazo horizontal mide 3,0 metros, el brazo de la silla mide 5,0 metros y forma 30 grados; la distancia al eje es 5,5 metros. En el segundo la velocidad es 7,1 metros por segundo, con el mismo brazo horizontal, el ángulo es 40 grados y la distancia 6,2 metros."></figure><p style="font-family:var(--font-mono);text-align:center">tan θ = (Velocidad)² ÷ ((Distancia) · g)</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('387de02e-3cc6-4a12-b75e-fa11f98e6d66', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un disco se mueve inicialmente con velocidad constante y en línea recta sobre una mesa que expulsa aire por unos agujeros. El disco no tiene contacto con la superficie de la mesa, de tal forma que queda suspendido en el aire y la fuerza de rozamiento que actúa sobre el disco es casi nula.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q106-disco.webp" loading="lazy" alt="Mesa de aire vista desde arriba, con el disco a la izquierda y una flecha rotulada v cero que indica que se mueve hacia la derecha con velocidad constante."></figure><p>Posteriormente se apaga el aire y el disco vuelve a quedar sobre la mesa, deslizándose hasta detenerse por causa de la fuerza de fricción.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('24c6ad4d-d06a-4d2a-9f26-6bd14227277f', 'situacion', 'FÍSICA', 'ctx-sit', '<p>La siguiente imagen muestra cómo la longitud de las aspas de un aerogenerador, medida en metros (m), se relaciona con la potencia eléctrica que puede generar, medida en kilovatios (kW).</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q107-aerogeneradores.webp" loading="lazy" alt="Cinco aerogeneradores de tamaño creciente. Debajo de cada uno, su potencia y la longitud de sus aspas: 300 kW con 30 m, 750 kW con 50 m, 1.800 kW con 80 m, 5.000 kW con 125 m y 20.000 kW con 250 m."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('89ad162b-a9a4-48fe-af5c-728ac11dafb6', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un correntómetro es un instrumento usado para medir la velocidad de una corriente de agua, el cual está equipado de una hélice que gira por la corriente líquida que choca con sus aspas, un contrapeso para evitar que se incline cuando se sumerge, una barra graduada para medir la profundidad y un tornillo de bloqueo para ajustar la hélice a la distancia requerida, como se muestra a continuación.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-helice.webp" loading="lazy" alt="Correntómetro: una hélice montada en un eje horizontal, sujeta a una barra vertical graduada de 01 a 05 mediante un tornillo de bloqueo, y un contrapeso en el extremo inferior de la barra."></figure><p>Actualmente, los correntómetros usan un contador de revoluciones, en donde los imanes establecen un contacto eléctrico con el sensor que envía la señal al contador, como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q108-sensor.webp" loading="lazy" alt="Detalle del mecanismo: una pieza curva con imanes incrustados pasa frente a un sensor, que queda fijo junto a ella."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d9c1f749-cf29-4908-a290-618c123993ca', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Se tienen 3 resistencias idénticas conectadas a una batería formando los circuitos mostrados en las figuras.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q109-circuitos.webp" loading="lazy" alt="Cuatro circuitos con la misma batería y tres resistencias iguales. En el primero las tres van una detrás de otra. En el segundo, dos van en paralelo y la tercera en serie con ellas. En el tercero, las tres van en paralelo, cada una en su propia rama. En el cuarto, dos van en paralelo y la tercera en serie."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('9f119ac5-3a51-4cce-ae71-b014ea695ee3', 'situacion', 'FÍSICA', 'ctx-sit', '<p>En un motor de combustión interna (como el de un carro), una mezcla de combustible, oxígeno y una chispa eléctrica producen una explosión controlada dentro del motor que genera movimiento del mismo.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('95d397d3-3d54-40b0-9e1f-4a1abf8f9679', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un diagrama de fases es una representación gráfica de un sistema material a diferentes presiones y temperaturas, reflejando el equilibrio entre las distintas fases. A continuación, se observa el diagrama de fases de un compuesto.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q111-fases.webp" loading="lazy" alt="Diagrama con la presión en el eje vertical y la temperatura en el horizontal. Tres regiones: sólido arriba a la izquierda, líquido arriba a la derecha y gas abajo, separadas por líneas que se cruzan en el punto triple; la frontera entre líquido y gas termina en el punto crítico. El punto A está en la región del sólido, arriba; el punto B está en la región del gas, abajo y más a la derecha."></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6d828e52-893e-4b6a-8faa-80fe14280627', 'situacion', 'FÍSICA', 'ctx-sit', '<p>En un recipiente de volumen y temperatura constante, se mide la forma como varía la presión de un gas a medida que se incrementa la cantidad de dicho gas en el recipiente a través de una válvula en intervalos de tiempo controlados. Como resultado de esta experiencia se determina que a medida que aumenta la masa del gas la presión en el recipiente también se incrementa.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bb50d745-7c5b-4e5d-86e6-8cc269304788', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Una esfera de vidrio rueda sobre una mesa de madera. A los pocos segundos de iniciado el movimiento la esfera se detiene.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8d5ee686-8bb6-4b66-ae55-5d110ebde491', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Dos partículas de polvo cargadas están separadas a una misma distancia de una pantalla larga que tiene una carga eléctrica positiva. La pantalla ejerce una fuerza sobre las partículas de igual magnitud y en direcciones opuestas, generando que las partículas experimenten aceleraciones como se muestra en la siguiente figura.</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q115-particulas.webp" loading="lazy" alt="Una pantalla vertical cargada positivamente. A un lado, a 1 cm, la partícula 1 con su vector aceleración apuntando hacia afuera; al otro lado, también a 1 cm, la partícula 2 con su vector aceleración apuntando hacia afuera en sentido contrario. El vector de la partícula 1 es el doble de largo que el de la partícula 2."></figure><p>Una estudiante nota que, de acuerdo a la figura, la magnitud de aceleración en la partícula 1 es el doble que la de la partícula 2.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('620760b6-7059-4465-a355-0f480383d3c3', 'situacion', 'FÍSICA', 'ctx-sit', '<p>Un estudiante enrolla una cuerda a una rueda con paletas, que tiene sujeto en su otro extremo una masa, y la deja caer para agitar el agua (ver Figura 1).</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q116-figura1.webp" loading="lazy" alt="Figura 1: un recipiente con agua, un termómetro sumergido y, dentro del agua, una rueda con paletas conectada por una cuerda que pasa por una polea en el borde."></figure><p>Cuando la masa se libera, y cae cierta altura, se observa un aumento en la lectura del termómetro, cuando todo el sistema está completamente aislado (ver Figura 2).</p><figure class="ctx-fig"><img src="img/figuras/fis/f2-q116-figura2.webp" loading="lazy" alt="Figura 2: el mismo montaje rotulado. Se señalan la lectura del termómetro, la rueda de paletas dentro del agua, la cuerda que pasa por la polea y la masa que cae una altura determinada."></figure><p>Para predecir el aumento de la temperatura del agua, el estudiante supone que toda la energía potencial gravitacional de la masa se convierte en calor. Sin embargo, al medir la temperatura al final del experimento nota que la temperatura del agua es un poco menor que la predicha.</p>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6b2d7d23-ef76-47bb-977f-ce1196fdb526', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '89f5bb68-ba04-4fd8-a55c-6a453ce94096', 'Dinámica y fuerzas',
  'De acuerdo con lo anterior, ¿por qué cuando se pone un semáforo de mayor masa la inclinación de las cuerdas aumenta, si se mantiene la misma tensión?',
  array['Porque cuando α es 90°, sen α = 1 y la tensión se iguala a la mitad de la masa.', 'Porque al aumentar α la tensión se iguala a cero.', 'Porque cuando α es 0°, sen α = 0 y la tensión tiende a una cantidad infinita.', 'Porque al aumentar α se compensa el aumento de la masa.'],
  'Mira qué está arriba y qué está abajo en la fracción. Si algo de arriba crece y el resultado no cambia, algo de abajo tuvo que crecer también.', 'publicada', 'modelo', 'f3119b59cf3a9902cc64d070979a44a4', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6b2d7d23-ef76-47bb-977f-ce1196fdb526', 3, 'En la ecuación la masa está arriba y el seno del ángulo abajo. Si la masa crece y la tensión tiene que quedarse igual, el denominador debe crecer en la misma proporción, y para eso el seno del ángulo tiene que aumentar, es decir, el ángulo tiene que abrirse. Por eso un semáforo más pesado cuelga con las cuerdas más inclinadas. Las demás opciones describen casos extremos del ángulo, pero ninguno explica la compensación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '8dada48c-4138-4a1b-a1a0-5267651f1c17', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'electricidad-y-magnetismo'),
  (select id from public.lotes where codigo = '2026-B'),
  'a68e8261-2a8a-49a3-b619-775ad3c63932', 'Electricidad y magnetismo',
  'De acuerdo con el diagrama, ¿cuál de las siguientes afirmaciones sobre la corriente de la bombilla 1 es correcta?',
  array['La corriente de la bombilla 1 es igual que la corriente de la bombilla 2.', 'La corriente de la bombilla 1 es el doble que la corriente de la bombilla 3.', 'La corriente de la bombilla 1 es un tercio de la corriente por la fuente de energía.', 'La corriente de la bombilla 1 es la mitad de la corriente por la fuente de energía.'],
  'Sigue el cable desde la fuente: donde no hay bifurcación, la corriente es la misma; donde se abre en dos ramas iguales, se parte en dos.', 'publicada', 'modelo', '4534c6083d9b4377b3c352a45f9e3df8', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8dada48c-4138-4a1b-a1a0-5267651f1c17', 1, 'La bombilla 1 está sola en el cable que sale de la fuente, así que por ella pasa toda la corriente. Más adelante ese cable se divide en dos ramas iguales, una para la bombilla 2 y otra para la bombilla 3, y la corriente se reparte por mitades entre ellas. Entonces por la bombilla 1 pasa el doble que por la 3, y también el doble que por la 2. Y como no se pierde corriente por el camino, por la bombilla 1 pasa exactamente lo mismo que por la fuente, no un tercio ni la mitad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '571e47b0-17d4-4323-be95-e577c3e9f924', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'ondas-y-sonido'),
  (select id from public.lotes where codigo = '2026-B'),
  'f20518d7-c0b3-4d08-bc0a-654e2136fcbc', 'Ondas y sonido',
  'Si se mira la cubeta con agua, por un lado, ¿cuál de las siguientes figuras muestra cómo son las ondas en la parte menos profunda?',
  array['<figure class="ctx-fig"><img src="img/figuras/fis/f2-q101-a.webp" loading="lazy" alt="Corte de la cubeta con el obstáculo a la derecha. Sobre la parte honda de la izquierda se ven ondas, y sobre el obstáculo la superficie queda casi lisa."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q101-b.webp" loading="lazy" alt="Corte de la cubeta con el obstáculo a la derecha. Las ondas son marcadas sobre la parte honda de la izquierda y se apagan sobre el obstáculo."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q101-c.webp" loading="lazy" alt="Corte de la cubeta con el obstáculo a la derecha. Sobre el obstáculo las ondas se ven más altas y más separadas que sobre la parte honda."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q101-d.webp" loading="lazy" alt="Corte de la cubeta con el obstáculo a la derecha. Sobre el obstáculo las ondas conservan la altura que traían pero van más juntas unas de otras."></figure>'],
  'Traduce el enunciado a dos cosas que mirar en el dibujo: separación entre crestas y altura de las crestas.', 'publicada', 'modelo', 'f3381ac4fa6bc923de4aa90d90c07562', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('571e47b0-17d4-4323-be95-e577c3e9f924', 3, 'El enunciado ya dice qué hay que buscar: sobre la parte menos profunda la longitud de onda disminuye y la amplitud se mantiene. Longitud de onda menor significa crestas más juntas, y amplitud igual significa crestas de la misma altura. La figura correcta es la única donde, encima del obstáculo, las ondas se aprietan sin achatarse. Las que alisan la superficie sobre el obstáculo cambian la amplitud, y la que las dibuja más altas también.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '037efa42-7dc1-41e2-a7c1-196077a2a436', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'c1f1693e-f444-4ca8-bdd1-9474d48d198c', 'Termodinámica',
  'Si se compara una lámina de aluminio con una de un nuevo material con mayor calor específico, ¿qué sucederá con la temperatura a la que llegará la nueva lámina, en comparación con la de aluminio?',
  array['Llegará a la misma temperatura, pero la lámina de aluminio tardará más tiempo.', 'Llegará a una mayor temperatura, pero la lámina de aluminio tardará más tiempo.', 'Llegará a la misma temperatura, pero la lámina del nuevo material tardará más tiempo.', 'Llegará a una mayor temperatura, pero la lámina del nuevo material tardará más tiempo.'],
  'Separa dos preguntas distintas: a qué temperatura llega y cuánto tarda en llegar. El calor específico contesta la segunda.', 'publicada', 'modelo', 'dbf81a56034b91aefefcecc686f1fe9a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('037efa42-7dc1-41e2-a7c1-196077a2a436', 2, 'El calor específico dice cuánta energía hay que darle a un material para subirle un grado, no hasta dónde puede subir. Las dos láminas están en el mismo panel, recibiendo el mismo calor del suelo y perdiéndolo hacia el mismo ambiente, así que las dos terminan en la misma temperatura de equilibrio. Lo que cambia es el camino: la de mayor calor específico necesita más energía por cada grado, así que tarda más en llegar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'dea9bb86-05bb-4407-8ba5-815fc8ec9960', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '4d2da40e-1d04-455a-81af-7af5dc5fdd26', 'Termodinámica',
  'Teniendo en cuenta los datos registrados en la tabla, ¿cuáles materiales se hunden en el agua y cuáles cambian de temperatura más fácilmente que el agua?',
  array['La madera y el acero se hunden, y ambos materiales cambian de temperatura más difícilmente en comparación con el agua.', 'Solo el acero se hunde en el agua, mientras que la madera y el acero cambian de temperatura más fácilmente en comparación con el agua.', 'La madera y el acero se hunden, mientras que solamente el acero cambia de temperatura más fácilmente en comparación con el agua.', 'Solo el acero se hunde en el agua, mientras que la madera y el acero, al tener un calor específico menor a 1, no cambian de temperatura.'],
  'Son dos comparaciones distintas contra el agua: una con la columna de densidad y otra con la de calor específico. Hazlas por separado.', 'publicada', 'modelo', '8909b3598a208cff08b6a532ac86618a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dea9bb86-05bb-4407-8ba5-815fc8ec9960', 1, 'Se hunde lo que es más denso que el agua. El agua está en 1.000, la madera en 400 —flota— y el acero en 7.850 —se hunde—. Para la temperatura hay que mirar el calor específico: cuanto más bajo, menos energía hace falta para calentar el material, o sea que cambia de temperatura con más facilidad. La madera está en 0,12 y el acero en 0,57, los dos por debajo del 1,07 del agua, así que los dos se calientan más fácil. Y que el calor específico sea menor que 1 no significa que no cambien de temperatura: significa lo contrario.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c2fbc656-d84b-4129-897f-4d259e7914e5', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'd879c9ab-dac2-4645-b655-2546a57d6b3f', 'Termodinámica',
  '¿Cuál de las siguientes gráficas representa la relación entre la presión y el volumen obtenida en el experimento?',
  array['<figure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Ejes de presión contra volumen con una recta que sube de izquierda a derecha." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">P</text><text x="284" y="191">V</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="46,172.9 262,35.1"/></svg></figure>', '<figure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Ejes de presión contra volumen con una curva que cae muy rápido al principio y luego se acerca al eje horizontal sin tocarlo." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">P</text><text x="284" y="191">V</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="50.8,30.2 58,67.9 70,104 86.8,127 110.8,143.4 142,154.8 178,163 221.2,168 262,171.2"/></svg></figure>', '<figure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Ejes de presión contra volumen con una recta que baja de izquierda a derecha." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">P</text><text x="284" y="191">V</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="46,35.1 262,172.9"/></svg></figure>', '<figure class="ctx-fig"><svg viewBox="0 0 300 220" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Ejes de presión contra volumen con una recta vertical en un único valor de volumen." font-family="var(--font-body), system-ui, sans-serif"><defs><marker id="pf" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0 0 L7 3 L0 6 z" fill="var(--color-ink-soft)"/></marker></defs><path d="M34 16V186H280" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><path d="M34 186V16" fill="none" stroke="var(--color-ink-soft)" stroke-width="1.6" marker-end="url(#pf)"/><g font-size="14" font-style="italic" fill="var(--color-ink)"><text x="24" y="18" text-anchor="end">P</text><text x="284" y="191">V</text></g><polyline fill="none" stroke="var(--color-accent)" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" points="154,177.8 154,30.2"/></svg></figure>'],
  'Multiplica cada presión por su volumen y mira si el resultado se repite. Si se repite, la gráfica no puede ser una recta.', 'publicada', 'modelo', '098c316b32748ec1f94e3e7deda64ea3', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c2fbc656-d84b-4129-897f-4d259e7914e5', 1, 'Hay que mirar cómo cambian los números juntos. Al duplicar la presión de 0,10 a 0,20 el volumen cae a la mitad, de 10 a 5; al triplicarla, el volumen queda en la tercera parte, 3,3; y al cuadruplicarla, en la cuarta, 2,5. En todos los casos el producto de presión por volumen da lo mismo, aproximadamente 1. Esa relación no es una recta: es una curva que baja muy rápido y después se va acercando al eje sin llegar a tocarlo, porque por más que se comprima, el volumen nunca llega a cero.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd0cbe4eb-2088-4667-8a00-688d1b598068', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'd7c16487-1f2f-4f87-9721-2869af2819d9', 'Dinámica y fuerzas',
  'Si Juan encuentra la ecuación que relaciona el ángulo (θ) y la velocidad, y sube a la atracción sabiendo que pesa el doble de su compañera, ¿qué se espera que le suceda al ángulo en ambas situaciones?',
  array['Que aumente el doble, ya que en la ecuación se muestra la gravedad, y el peso depende de la aceleración de la gravedad y de la masa.', 'Que se mantenga igual, ya que en la ecuación no aparece la masa: el ángulo solo depende de la velocidad y de la distancia.', 'Que disminuya 10 grados, pues como se observa en la ecuación, al aumentar la velocidad el ángulo de rotación del sistema disminuye.', 'Que aumente la mitad, puesto que al elevar la velocidad al cuadrado el ángulo de rotación aumenta en esa misma proporción, debido a la masa.'],
  'Antes de razonar, haz la lista de lo que aparece en la ecuación. Lo que no aparece, no influye.', 'publicada', 'modelo', '0ce3d83afb588b51e6a9fb1923bd6d9b', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d0cbe4eb-2088-4667-8a00-688d1b598068', 1, 'En la ecuación aparecen tres cosas: la velocidad, la distancia y la gravedad. La masa no está por ningún lado, así que subirse alguien que pesa el doble no cambia el resultado. Es lo mismo que pasa con los cuerpos que caen: la masa se cancela. Si la atracción gira a la misma velocidad y a la misma distancia, el brazo se inclina el mismo ángulo con Juan que con su compañera.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c4327263-e124-4a79-a091-314e89939de3', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'cinematica'),
  (select id from public.lotes where codigo = '2026-B'),
  '387de02e-3cc6-4a12-b75e-fa11f98e6d66', 'Cinemática',
  '¿Cuál de las siguientes gráficas ilustra la velocidad del disco en el tiempo?',
  array['<figure class="ctx-fig"><img src="img/figuras/fis/f2-q106-a.webp" loading="lazy" alt="Gráfica de velocidad contra tiempo: la velocidad sube desde cero en línea recta hasta v cero y a partir de ahí se mantiene constante."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q106-b.webp" loading="lazy" alt="Gráfica de velocidad contra tiempo: la velocidad arranca en v cero, baja en línea recta hasta un valor intermedio y desde ahí se mantiene constante sin llegar a cero."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q106-c.webp" loading="lazy" alt="Gráfica de velocidad contra tiempo: la velocidad sube desde cero hasta v cero y enseguida baja en línea recta hasta detenerse."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q106-d.webp" loading="lazy" alt="Gráfica de velocidad contra tiempo: la velocidad se mantiene constante en v cero durante un tramo y después baja en línea recta hasta cero."></figure>'],
  'Divide el movimiento en etapas y dibuja cada una antes de mirar las opciones: primero velocidad constante, después frenado.', 'publicada', 'modelo', '5cdbd9ba0a63291c68c8e13f29fe1b7d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c4327263-e124-4a79-a091-314e89939de3', 3, 'El movimiento tiene dos etapas. Mientras el aire está encendido no hay rozamiento, así que la velocidad no cambia: eso es un tramo horizontal a la altura de v cero. Cuando se apaga el aire aparece la fricción, que frena el disco de manera pareja hasta dejarlo quieto: eso es un tramo recto que baja hasta cero. La gráfica correcta es la que tiene esas dos partes en ese orden. Las que empiezan subiendo desde cero contradicen el enunciado, que dice que el disco ya venía moviéndose.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c7dbb0f5-17f9-43e6-ad98-89a6dee57b22', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'energia-y-trabajo'),
  (select id from public.lotes where codigo = '2026-B'),
  '24c6ad4d-d06a-4d2a-9f26-6bd14227277f', 'Energía y trabajo',
  '¿Cuál de las siguientes gráficas muestra correctamente los datos de potencia eléctrica respecto a la longitud de las aspas de un aerogenerador?',
  array['<figure class="ctx-fig"><img src="img/figuras/fis/f2-q107-a.webp" loading="lazy" alt="Gráfica de dispersión con el eje horizontal de longitud de aspas marcado de 0 a 6.000 metros y el vertical de potencia de 0 a 6.000 kilovatios."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q107-b.webp" loading="lazy" alt="Gráfica de dispersión con el eje horizontal marcado en 0, 30, 50, 80, 125 y 250 metros y el vertical en 0, 300, 750, 1.800, 5.000 y 20.000 kilovatios. El punto de 250 metros queda a la altura de 5.000 kilovatios."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q107-c.webp" loading="lazy" alt="Gráfica de dispersión con el eje horizontal de 0 a 25.000 metros y el vertical de 0 a 300 kilovatios."></figure>', '<figure class="ctx-fig"><img src="img/figuras/fis/f2-q107-d.webp" loading="lazy" alt="Gráfica de dispersión con el eje horizontal repartido de 0 a 300 metros de cincuenta en cincuenta y el vertical de 0 a 25.000 kilovatios. Los puntos suben despacio al principio y el último, en 250 metros, llega a 20.000 kilovatios."></figure>'],
  'Antes de mirar la forma de la nube de puntos, comprueba hasta dónde llega cada eje y busca el dato más grande en la gráfica.', 'publicada', 'modelo', '6a10396c1fd9578e2841bfcf831d7937', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c7dbb0f5-17f9-43e6-ad98-89a6dee57b22', 3, 'Hay que revisar dos cosas en cada gráfica: que los ejes lleguen hasta donde llegan los datos y que los puntos queden donde toca. Las aspas van de 30 a 250 metros y las potencias de 300 a 20.000 kilovatios. Dos de las gráficas usan ejes que no corresponden, uno que llega a miles de metros de aspa y otro que se queda en 300 kilovatios. De las dos que quedan, una coloca el aerogenerador de 250 metros en 5.000 kilovatios cuando la imagen dice 20.000. La correcta es la que reparte los ejes de manera pareja y pone cada punto en su valor.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4bfa48e3-2fea-4787-bbb7-af78058f3eee', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'electricidad-y-magnetismo'),
  (select id from public.lotes where codigo = '2026-B'),
  '89ad162b-a9a4-48fe-af5c-728ac11dafb6', 'Electricidad y magnetismo',
  'De acuerdo con la información anterior, ¿en qué parte del correntómetro se debe ubicar el imán para que el contador de revoluciones indique la velocidad de la corriente?',
  array['En la barra graduada, porque la velocidad del agua depende de la profundidad.', 'En el tornillo de bloqueo, porque el imán estaría fijo en todo momento.', 'En el contrapeso, porque es el elemento que da estabilidad al correntómetro.', 'En la hélice, porque esta gira gracias a la velocidad del agua.'],
  'Pregúntate qué pieza se mueve cuando el agua corre. El imán tiene que ir en esa, no en las que sostienen el aparato.', 'publicada', 'modelo', '2691133dcb0effb2378d382fe063384a', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4bfa48e3-2fea-4787-bbb7-af78058f3eee', 3, 'El contador cuenta revoluciones, y para que cuente algo el imán tiene que pasar una y otra vez frente al sensor. Eso solo ocurre si el imán va montado en la pieza que da vueltas, que es la hélice. La barra, el tornillo y el contrapeso están quietos mientras se mide: un imán ahí pasaría frente al sensor cero veces por minuto, sin importar qué tan rápido vaya el agua.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '833b8171-2896-4882-b86b-22499a6bea25', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'electricidad-y-magnetismo'),
  (select id from public.lotes where codigo = '2026-B'),
  'd9c1f749-cf29-4908-a290-618c123993ca', 'Electricidad y magnetismo',
  'El circuito en el que la corriente total alcanza su mayor valor es',
  array['1', '2', '3', '4'],
  'Cuenta cuántos caminos distintos tiene la corriente para volver a la batería. Cuantos más, menos se opone el circuito.', 'publicada', 'modelo', '9142a7ece50d0e38c6f0949ea12b47d1', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('833b8171-2896-4882-b86b-22499a6bea25', 2, 'Con la misma batería, pasa más corriente por donde hay menos resistencia. Poner resistencias una detrás de otra las suma, así que el circuito en serie es el que más se opone. Ponerlas en ramas paralelas es abrirle al corriente más caminos a la vez, y eso baja la resistencia total. Las tres en paralelo es el caso con más caminos y la menor resistencia de los cuatro —la tercera parte de una sola—, así que por ahí pasa la mayor corriente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'a2890601-1bd8-44de-b8bf-e0fd4dfc159e', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'energia-y-trabajo'),
  (select id from public.lotes where codigo = '2026-B'),
  '9f119ac5-3a51-4cce-ae71-b014ea695ee3', 'Energía y trabajo',
  'Según lo anterior, el proceso de transformación de energía que se da dentro del motor es de',
  array['energía mecánica a energía térmica.', 'energía mecánica a energía química.', 'energía química a energía mecánica.', 'energía térmica a energía química.'],
  'Ubica dónde estaba guardada la energía antes de encender el motor y en qué se nota después.', 'publicada', 'modelo', '1b99fde8b90c1204e553b288a6ac31c6', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a2890601-1bd8-44de-b8bf-e0fd4dfc159e', 2, 'La energía está guardada en el combustible, en los enlaces de sus moléculas: eso es energía química. La chispa dispara la explosión, que libera esa energía y empuja las piezas del motor, es decir, produce movimiento: energía mecánica. El proceso va entonces de química a mecánica. En el camino hay calor, sí, pero el enunciado pregunta de dónde sale la energía y en qué termina.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5da71fe6-83ff-416d-bd76-2d53f56a87ee', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '95d397d3-3d54-40b0-9e1f-4a1abf8f9679', 'Termodinámica',
  'Teniendo en cuenta la gráfica anterior, es posible afirmar que para pasar del punto B al punto A se requiere',
  array['mantener constante la temperatura y aumentar la presión del sistema.', 'aumentar la presión y disminuir la temperatura del sistema.', 'disminuir la presión y aumentar la temperatura del sistema.', 'aumentar la temperatura y mantener constante la presión del sistema.'],
  'Convierte el movimiento en el dibujo a dos frases: arriba o abajo es la presión; izquierda o derecha es la temperatura.', 'publicada', 'modelo', '2a8eed4970767c6c0fb52b2831e1639a', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5da71fe6-83ff-416d-bd76-2d53f56a87ee', 1, 'En este diagrama la presión se lee hacia arriba y la temperatura hacia la derecha. El punto B está abajo y a la derecha; el punto A está arriba y a la izquierda. Para ir de B a A hay que subir, que es aumentar la presión, y moverse hacia la izquierda, que es bajar la temperatura. Las dos cosas a la vez: si solo se sube la presión sin enfriar, o solo se enfría sin comprimir, no se llega.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b06abf61-da82-4536-9729-167dfed6e332', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'termodinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  '6d828e52-893e-4b6a-8faa-80fe14280627', 'Termodinámica',
  'La manera adecuada de presentar los resultados de la experiencia es',
  array['por medio de fotografías en las cuales se muestre la construcción del recipiente y el diseño de los instrumentos usados para medir la presión.', 'por medio de una tabla y una gráfica en las cuales se muestren los cambios en los valores de presión en cada instante que se agrega gas al recipiente.', 'por medio de un escrito que mencione todas las propiedades de los gases y la variación del comportamiento de sus variables en relación con las demás.', 'por medio de un diagrama de flujo el cual muestre cada uno de los pasos que se desarrollaron para agregar el gas al recipiente.'],
  'Distingue entre contar cómo se hizo el experimento y mostrar qué dio. La pregunta va por lo segundo.', 'publicada', 'modelo', 'efb9432f3579d70b7da049bc855b3d0e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b06abf61-da82-4536-9729-167dfed6e332', 1, 'Lo que el experimento produjo son parejas de números: cuánto gas hay y qué presión se midió. Presentar resultados es mostrar esos números y lo que dicen, y para eso sirven una tabla, que los guarda uno por uno, y una gráfica, que deja ver de un vistazo que la presión sube con la masa. Las fotografías muestran el montaje pero no los datos; el escrito general habla de gases en abstracto sin usar lo medido; y el diagrama de flujo describe el procedimiento, que es otra sección del informe.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'b3a3281f-3677-441a-913e-58169fb2b1cc', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'dinamica'),
  (select id from public.lotes where codigo = '2026-B'),
  'bb50d745-7c5b-4e5d-86e6-8cc269304788', 'Dinámica y fuerzas',
  'Lo sucedido con el movimiento de la esfera es que',
  array['la fuerza neta sobre la esfera es en sentido contrario a su movimiento.', 'todos los cuerpos tienden naturalmente a detenerse.', 'la masa de la esfera incide en su detención.', 'la aceleración de la esfera es positiva en el sentido del movimiento.'],
  'Si algo frena, hay una fuerza apuntando al revés del movimiento. Busca cuál es y en qué sentido va.', 'publicada', 'modelo', '403ec2c3585f02bcfa8891b57627aa23', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b3a3281f-3677-441a-913e-58169fb2b1cc', 0, 'Un cuerpo en movimiento solo se frena si algo lo empuja en contra. Aquí ese algo es el rozamiento entre la esfera y la madera, que apunta al revés del avance: por eso la esfera pierde velocidad hasta parar. Que los cuerpos «tiendan a detenerse» no es una ley, es justo lo contrario de lo que dice la inercia: sin ninguna fuerza en contra la esfera habría seguido rodando. Y si la aceleración fuera en el sentido del movimiento, la esfera iría cada vez más rápido.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '20d75d05-4877-4a25-a96e-2b4a7da901c1', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'electricidad-y-magnetismo'),
  (select id from public.lotes where codigo = '2026-B'),
  '8d5ee686-8bb6-4b66-ae55-5d110ebde491', 'Electricidad y magnetismo',
  '¿A qué se debe que la magnitud de la aceleración de las partículas no sea la misma?',
  array['A que la masa de las partículas es diferente.', 'A que la dirección de las fuerzas es diferente.', 'A que la cantidad de carga de las partículas es igual.', 'A que la distancia de separación es la misma.'],
  'Tacha del enunciado todo lo que dice que es igual en las dos partículas. Lo que sobra es la respuesta.', 'publicada', 'modelo', 'bc5782fc3d342d9fab5e84e0e1f8864e', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('20d75d05-4877-4a25-a96e-2b4a7da901c1', 0, 'El enunciado ya descarta casi todo: dice que la fuerza sobre las dos tiene la misma magnitud y que están a la misma distancia. Con la misma fuerza, la aceleración depende únicamente de la masa, y es al revés: cuanta más masa, menos acelera. Si una acelera el doble que la otra, es porque tiene la mitad de masa. Que las direcciones sean opuestas cambia hacia dónde va cada una, no qué tan rápido gana velocidad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c812961c-eb3a-40f8-a3e1-decdb9aaee62', 'fis',
  (select id from public.temas where materia = 'fis' and codigo = 'energia-y-trabajo'),
  (select id from public.lotes where codigo = '2026-B'),
  '620760b6-7059-4465-a355-0f480383d3c3', 'Energía y trabajo',
  '¿Cuál de las siguientes opciones puede ser una razón para que el termómetro registre una temperatura menor que la predicha?',
  array['Una parte pequeña de la energía potencial de la masa se transforma en energía cinética de la masa y de la rueda.', 'Se aumenta la energía potencial de la rueda, causando un flujo de temperatura que se refleja en menos calor cedido.', 'Aumentar la energía potencial de la masa aumenta la temperatura del agua, pero hay una disminución del flujo de calor.', 'Parte del calor que genera la masa se transforma en energía potencial, lo cual causa que disminuya la temperatura del agua.'],
  'Compara lo que supone la predicción con lo que de verdad pasa al final de la caída. Pregúntate si toda la energía alcanzó a convertirse.', 'publicada', 'modelo', 'd4c02f64a5b18aceabfbac5a17bd53f5', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c812961c-eb3a-40f8-a3e1-decdb9aaee62', 0, 'La predicción supone que absolutamente toda la energía de la caída termina calentando el agua. Pero al final del recorrido la masa sigue bajando, o sea que se quedó con algo de energía de movimiento, y la rueda también está girando. Esa parte todavía no se ha convertido en calor, así que el agua recibe un poco menos de lo previsto y el termómetro marca menos. Las otras opciones invierten el sentido del proceso: convierten calor en energía potencial o hacen que la rueda gane altura, y nada de eso ocurre aquí.');

